"use client";

import * as React from "react";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { cn } from "@/lib/utils";

import { isDogecoinP2pkhAddress } from "./dogecoin";
import { PaymentDialogBody } from "./payment-button-parts";
import type { DogecoinPaymentButtonProps } from "./payment-button-types";
import {
  useMempoolWatch,
  usePaymentResolution,
} from "./use-payment-button-state";
import { watchStatusMessage } from "./watch-status";

export type {
  DogecoinPaymentButtonProps,
  DogecoinPaymentResolveFn,
  MempoolWatchConfig,
} from "./payment-button-types";

const countModes = ({
  address,
  resolveAddress,
  xpub,
}: DogecoinPaymentButtonProps): number =>
  [address, resolveAddress, xpub].filter(Boolean).length;

export const DogecoinPaymentButton = (props: DogecoinPaymentButtonProps) => {
  if (countModes(props) !== 1) {
    throw new Error(
      "DogecoinPaymentButton requires exactly one of `address`, `resolveAddress`, or `xpub`."
    );
  }

  if (props.address && !isDogecoinP2pkhAddress(props.address)) {
    throw new Error(
      "DogecoinPaymentButton received an invalid Dogecoin address."
    );
  }

  const [open, setOpen] = React.useState(false);
  const {
    address: staticAddress,
    addressIndexStep,
    amount,
    buttonLabel,
    checker,
    children,
    className,
    maxAttempts,
    mempoolWatch,
    resolveAddress,
    xpub,
  } = props;

  const resolution = usePaymentResolution({
    address: staticAddress,
    addressIndexStep,
    amount,
    checker,
    maxAttempts,
    open,
    resolveAddress,
    xpub,
  });

  const watch = useMempoolWatch({
    amount,
    endpoint: mempoolWatch?.endpoint,
    fetchImpl: mempoolWatch?.fetchImpl,
    onPaymentAppeared: props.onPaymentAppeared,
    open,
    paymentAddress: resolution.payment?.address,
    resolutionStatus: resolution.status,
  });

  const watchMessage = watchStatusMessage(watch.status, watch.errorMessage);

  const handleRetryOpen = () => {
    setOpen(false);
    queueMicrotask(() => {
      setOpen(true);
    });
  };

  const handleRetryWatch = () => {
    watch.retryWatch();
  };

  return (
    <Dialog onOpenChange={setOpen} open={open}>
      <Button
        aria-expanded={open}
        aria-haspopup="dialog"
        className={cn(className)}
        onClick={() => {
          setOpen(true);
        }}
        type="button"
      >
        {children ?? buttonLabel ?? "Send me Dogecoin"}
      </Button>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Send me Dogecoin</DialogTitle>
          <DialogDescription>
            Scan the QR code or copy the address below to send DOGE.
          </DialogDescription>
        </DialogHeader>

        <PaymentDialogBody
          amount={amount}
          appearedPayload={watch.appearedPayload}
          errorMessage={resolution.errorMessage}
          mempoolWatchEnabled={Boolean(mempoolWatch)}
          onRetryOpen={handleRetryOpen}
          onRetryWatch={handleRetryWatch}
          payment={resolution.payment}
          status={resolution.status}
          watchMessage={watchMessage}
          watchStatus={watch.status}
        />
      </DialogContent>
    </Dialog>
  );
};

import { ripemd160 } from "@noble/hashes/legacy.js";
import { sha256 } from "@noble/hashes/sha2.js";
import { base58check } from "@scure/base";
import { HDKey } from "@scure/bip32";

const b58c = base58check(sha256);

/** Dogecoin Core BIP32 version bytes (`dgpv` / `dgub`). */
export const DOGECOIN_BIP32_VERSIONS = {
  private: 0x02_fa_c3_98,
  public: 0x02_fa_ca_fd,
} as const;

/** Bitcoin BIP32 version bytes accepted for account-public-key interchange. */
export const BITCOIN_BIP32_VERSIONS = {
  private: 0x04_88_ad_e4,
  public: 0x04_88_b2_1e,
} as const;

export const DOGECOIN_P2PKH_VERSION = 0x1e;
export const ACCOUNT_XPUB_DEPTH = 3;
export const EXTERNAL_CHAIN = 0;

export class DogecoinKeyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "DogecoinKeyError";
  }
}

const detectPublicVersions = (extendedKey: string) => {
  if (extendedKey.startsWith("dgub")) {
    return DOGECOIN_BIP32_VERSIONS;
  }

  if (extendedKey.startsWith("xpub")) {
    return BITCOIN_BIP32_VERSIONS;
  }

  if (
    extendedKey.startsWith("dgpv") ||
    extendedKey.startsWith("xprv") ||
    extendedKey.startsWith("tprv") ||
    extendedKey.startsWith("tpub")
  ) {
    throw new DogecoinKeyError(
      "Private or testnet extended keys are not accepted. Provide an account-level dgub or xpub."
    );
  }

  throw new DogecoinKeyError(
    "Unsupported extended key encoding. Provide an account-level dgub or xpub."
  );
};

/**
 * Parse a Dogecoin BIP44 account-level public key (`m/44'/3'/0'`).
 * Accepts Dogecoin-native `dgub` and Bitcoin-compatible `xpub` encodings.
 */
export const parseAccountXpub = (extendedKey: string): HDKey => {
  const trimmed = extendedKey.trim();
  const versions = detectPublicVersions(trimmed);

  let key: HDKey;
  try {
    key = HDKey.fromExtendedKey(trimmed, versions);
  } catch {
    throw new DogecoinKeyError("Invalid extended public key encoding.");
  }

  if (key.privateKey) {
    throw new DogecoinKeyError("Private extended keys are not accepted.");
  }

  if (key.depth !== ACCOUNT_XPUB_DEPTH) {
    const depthHint =
      key.depth === ACCOUNT_XPUB_DEPTH + 1
        ? " This looks like a receive-chain key at m/44'/3'/0'/0 — export the account key at m/44'/3'/0' instead."
        : "";
    throw new DogecoinKeyError(
      `Expected an account-level key at depth ${ACCOUNT_XPUB_DEPTH} (m/44'/3'/0'), got depth ${key.depth}.${depthHint}`
    );
  }

  return key;
};

export const publicKeyToP2pkhAddress = (publicKey: Uint8Array): string => {
  const hash = ripemd160(sha256(publicKey));
  const payload = new Uint8Array(21);
  payload[0] = DOGECOIN_P2PKH_VERSION;
  payload.set(hash, 1);
  return b58c.encode(payload);
};

/**
 * Derive a mainnet Dogecoin P2PKH payment address for the external chain.
 * Relative path from the account xpub: `m/0/<addressIndex>`.
 */
export const derivePaymentAddress = (
  accountXpub: string,
  addressIndex: number
): string => {
  if (!Number.isInteger(addressIndex) || addressIndex < 0) {
    throw new DogecoinKeyError("Address index must be a non-negative integer.");
  }

  const account = parseAccountXpub(accountXpub);
  const child = account.derive(`m/${EXTERNAL_CHAIN}/${addressIndex}`);

  if (!child.publicKey) {
    throw new DogecoinKeyError(
      "Failed to derive a public key for the address."
    );
  }

  return publicKeyToP2pkhAddress(child.publicKey);
};

export const isDogecoinP2pkhAddress = (address: string): boolean => {
  try {
    const decoded = b58c.decode(address);
    return decoded.length === 21 && decoded[0] === DOGECOIN_P2PKH_VERSION;
  } catch {
    return false;
  }
};

export const DEFAULT_ADDRESS_INDEX_STEP = 19;
export const DEFAULT_MAX_ATTEMPTS = 20;

export type AddressUsageChecker = (
  address: string,
  signal?: AbortSignal
) => Promise<boolean>;

export type SelectionMode =
  | "verified"
  | "transient-fallback"
  | "exhausted"
  | "unchecked";

export interface SelectionState {
  startIndex: number;
  uncheckedMode: boolean;
}

export interface AddressSelectionResult {
  address: string;
  index: number;
  mode: SelectionMode;
  nextStartIndex: number;
  uncheckedMode: boolean;
}

export interface AddressSelectionOptions {
  addressIndexStep?: number;
  checker: AddressUsageChecker;
  deriveAddress: (index: number) => string;
  maxAttempts?: number;
  signal?: AbortSignal;
  startIndex?: number;
  uncheckedMode?: boolean;
}

const assertNotAborted = (signal?: AbortSignal): void => {
  if (signal?.aborted) {
    throw new DOMException("Address selection aborted.", "AbortError");
  }
};

/**
 * Select a payment address using the stepped discovery sequence.
 *
 * From `startIndex`, candidates are `start, start+step, …` for up to
 * `maxAttempts` checks. An unused address is reused on later opens until it
 * becomes used. Provider errors fall back to the next unchecked index for the
 * current opening and retry discovery from that index next time. After
 * `maxAttempts` used results, the final known-used candidate is returned and
 * the instance enters permanent unchecked mode (increment-only, no checks).
 */
export const selectPaymentAddress = async (
  options: AddressSelectionOptions
): Promise<AddressSelectionResult> => {
  const addressIndexStep =
    options.addressIndexStep ?? DEFAULT_ADDRESS_INDEX_STEP;
  const maxAttempts = options.maxAttempts ?? DEFAULT_MAX_ATTEMPTS;
  const startIndex = options.startIndex ?? 0;
  const uncheckedMode = options.uncheckedMode ?? false;

  if (!Number.isInteger(addressIndexStep) || addressIndexStep < 1) {
    throw new Error("addressIndexStep must be a positive integer.");
  }

  if (!Number.isInteger(maxAttempts) || maxAttempts < 1) {
    throw new Error("maxAttempts must be a positive integer.");
  }

  if (!Number.isInteger(startIndex) || startIndex < 0) {
    throw new Error("startIndex must be a non-negative integer.");
  }

  assertNotAborted(options.signal);

  if (uncheckedMode) {
    const address = options.deriveAddress(startIndex);
    return {
      address,
      index: startIndex,
      mode: "unchecked",
      nextStartIndex: startIndex + addressIndexStep,
      uncheckedMode: true,
    };
  }

  let lastCheckedIndex = startIndex;
  let lastCheckedAddress = options.deriveAddress(startIndex);

  for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
    assertNotAborted(options.signal);

    const index = startIndex + attempt * addressIndexStep;
    const address =
      attempt === 0 ? lastCheckedAddress : options.deriveAddress(index);
    lastCheckedIndex = index;
    lastCheckedAddress = address;

    let used: boolean;
    try {
      used = await options.checker(address, options.signal);
    } catch (error) {
      if (error instanceof DOMException && error.name === "AbortError") {
        throw error;
      }

      const fallbackIndex = index + addressIndexStep;
      return {
        address: options.deriveAddress(fallbackIndex),
        index: fallbackIndex,
        mode: "transient-fallback",
        nextStartIndex: fallbackIndex,
        uncheckedMode: false,
      };
    }

    assertNotAborted(options.signal);

    if (!used) {
      return {
        address,
        index,
        mode: "verified",
        nextStartIndex: index,
        uncheckedMode: false,
      };
    }
  }

  return {
    address: lastCheckedAddress,
    index: lastCheckedIndex,
    mode: "exhausted",
    nextStartIndex: lastCheckedIndex + addressIndexStep,
    uncheckedMode: true,
  };
};

export const createInitialSelectionState = (): SelectionState => ({
  startIndex: 0,
  uncheckedMode: false,
});

import type { AddressUsageChecker } from "./address-selection";

export const BLOCKCYPHER_DOGE_ADDRESS_URL =
  "https://api.blockcypher.com/v1/doge/main/addrs";

/** Stay under BlockCypher's free-tier 3 req/sec limit. */
export const DEFAULT_REQUEST_INTERVAL_MS = 350;

export interface BlockCypherCheckerOptions {
  baseUrl?: string;
  fetchImpl?: typeof fetch;
  requestIntervalMs?: number;
  token?: string;
}

interface BlockCypherAddressResponse {
  final_n_tx?: number;
}

interface TimeoutRef {
  current?: ReturnType<typeof setTimeout>;
}

let lastRequestAt = 0;

const sleep = (ms: number, signal?: AbortSignal): Promise<void> =>
  // oxlint-disable-next-line promise/avoid-new -- Abortable timers require coordinating resolve and reject callbacks.
  new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(new DOMException("Address check aborted.", "AbortError"));
      return;
    }

    const timeoutRef: TimeoutRef = {};

    const onAbort = () => {
      if (timeoutRef.current !== undefined) {
        clearTimeout(timeoutRef.current);
      }
      reject(new DOMException("Address check aborted.", "AbortError"));
    };

    timeoutRef.current = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);

    signal?.addEventListener("abort", onAbort, { once: true });
  });

const paceRequests = async (
  intervalMs: number,
  signal?: AbortSignal
): Promise<void> => {
  const elapsed = Date.now() - lastRequestAt;
  if (elapsed < intervalMs) {
    await sleep(intervalMs - elapsed, signal);
  }
  lastRequestAt = Date.now();
};

/**
 * Default Address Usage Checker backed by BlockCypher's Dogecoin address API.
 * An address is used when `final_n_tx > 0` (confirmed or mempool activity).
 */
export const createBlockCypherAddressUsageChecker = (
  options: BlockCypherCheckerOptions = {}
): AddressUsageChecker => {
  const fetchImpl = options.fetchImpl ?? fetch;
  const intervalMs = options.requestIntervalMs ?? DEFAULT_REQUEST_INTERVAL_MS;
  const baseUrl = options.baseUrl ?? BLOCKCYPHER_DOGE_ADDRESS_URL;

  return async (address, signal) => {
    await paceRequests(intervalMs, signal);

    const url = new URL(`${baseUrl}/${address}`);
    if (options.token) {
      url.searchParams.set("token", options.token);
    }

    const response = await fetchImpl(url, {
      headers: { Accept: "application/json" },
      method: "GET",
      signal,
    });

    if (!response.ok) {
      throw new Error(
        `BlockCypher address lookup failed with status ${response.status}.`
      );
    }

    const body = (await response.json()) as BlockCypherAddressResponse;

    if (typeof body.final_n_tx !== "number") {
      throw new TypeError("BlockCypher response is missing final_n_tx.");
    }

    return body.final_n_tx > 0;
  };
};

export const defaultAddressUsageChecker =
  createBlockCypherAddressUsageChecker();

import { isDogecoinP2pkhAddress } from "./dogecoin";
import { normalizeDogecoinAmount } from "./payment-uri";

export const DOGE_BASE_UNITS_PER_COIN = 100_000_000;

export const MEMPOOL_WATCH_APPEARED_EVENT = "mempool.watch.appeared" as const;
export const MEMPOOL_WATCH_TIMEOUT_EVENT = "mempool.watch.timeout" as const;

export type MempoolWatchSource = "catchup" | "live";

export interface MempoolWatchOutput {
  valueBase: string;
  vout: number;
}

export interface MempoolWatchAppearedPayload {
  address: string;
  detectedAt: string;
  outputs: MempoolWatchOutput[];
  source: MempoolWatchSource;
  txid: string;
}

export interface MempoolWatchTimeoutPayload {
  address: string;
  expiresAt: string;
}

export type MempoolWatchStatus =
  | "idle"
  | "watching"
  | "appeared"
  | "timeout"
  | "busy"
  | "error";

export class MempoolWatchError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "MempoolWatchError";
  }
}

export interface WatchMempoolOptions {
  address: string;
  endpoint: string;
  fetchImpl?: typeof fetch;
  minValueBase?: string;
  onAppeared: (payload: MempoolWatchAppearedPayload) => void;
  onBusy?: () => void;
  onError?: (error: Error) => void;
  onTimeout: (payload: MempoolWatchTimeoutPayload) => void;
  signal?: AbortSignal;
}

export interface WatchMempoolHandle {
  close: () => void;
}

interface SseFrame {
  data: string;
  event: string;
}

const BASE_UNITS_PATTERN = /^(?:0|[1-9]\d*)$/u;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const parseSseFrame = (raw: string): SseFrame | null => {
  const lines = raw.split(/\r?\n/u);
  let event = "message";
  const dataLines: string[] = [];

  for (const line of lines) {
    if (line.length === 0 || line.startsWith(":")) {
      continue;
    }

    const separatorIndex = line.indexOf(":");
    const field = separatorIndex === -1 ? line : line.slice(0, separatorIndex);
    let value = separatorIndex === -1 ? "" : line.slice(separatorIndex + 1);
    if (value.startsWith(" ")) {
      value = value.slice(1);
    }

    if (field === "event") {
      event = value;
    } else if (field === "data") {
      dataLines.push(value);
    }
  }

  if (dataLines.length === 0) {
    return null;
  }

  return {
    data: dataLines.join("\n"),
    event,
  };
};

/**
 * Convert a positive DOGE decimal string into base units
 * (1 DOGE = 100000000) as a non-negative integer string.
 */
export const dogeAmountToBaseUnits = (amount: string): string => {
  const normalized = normalizeDogecoinAmount(amount);
  const [wholePart, fractionalPart = ""] = normalized.split(".");
  const fractional = fractionalPart.padEnd(8, "0");
  const baseUnits =
    Number(wholePart) * DOGE_BASE_UNITS_PER_COIN + Number(fractional);

  if (!Number.isSafeInteger(baseUnits)) {
    throw new MempoolWatchError(
      "Amount is too large to convert to base units exactly."
    );
  }

  return String(baseUnits);
};

export const isNonNegativeBaseUnits = (value: string): boolean =>
  BASE_UNITS_PATTERN.test(value);

export const parseMempoolWatchAppearedPayload = (
  data: string
): MempoolWatchAppearedPayload => {
  let parsed: unknown;
  try {
    parsed = JSON.parse(data) as unknown;
  } catch {
    throw new MempoolWatchError("Appeared event payload is not valid JSON.");
  }

  if (!isRecord(parsed)) {
    throw new MempoolWatchError("Appeared event payload must be an object.");
  }

  const { address, detectedAt, outputs, source, txid } = parsed;

  if (typeof address !== "string" || !isDogecoinP2pkhAddress(address)) {
    throw new MempoolWatchError("Appeared event is missing a valid address.");
  }

  if (typeof txid !== "string" || txid.length === 0) {
    throw new MempoolWatchError("Appeared event is missing a txid.");
  }

  if (typeof detectedAt !== "string" || detectedAt.length === 0) {
    throw new MempoolWatchError("Appeared event is missing detectedAt.");
  }

  if (source !== "catchup" && source !== "live") {
    throw new MempoolWatchError("Appeared event has an invalid source.");
  }

  if (!Array.isArray(outputs) || outputs.length === 0) {
    throw new MempoolWatchError("Appeared event is missing outputs.");
  }

  const normalizedOutputs = outputs.map((output, index) => {
    if (!isRecord(output)) {
      throw new MempoolWatchError(
        `Appeared event output at index ${index} must be an object.`
      );
    }

    if (typeof output.vout !== "number" || !Number.isInteger(output.vout)) {
      throw new MempoolWatchError(
        `Appeared event output at index ${index} has an invalid vout.`
      );
    }

    if (
      typeof output.valueBase !== "string" ||
      !isNonNegativeBaseUnits(output.valueBase)
    ) {
      throw new MempoolWatchError(
        `Appeared event output at index ${index} has an invalid valueBase.`
      );
    }

    return {
      valueBase: output.valueBase,
      vout: output.vout,
    };
  });

  return {
    address,
    detectedAt,
    outputs: normalizedOutputs,
    source,
    txid,
  };
};

export const parseMempoolWatchTimeoutPayload = (
  data: string
): MempoolWatchTimeoutPayload => {
  let parsed: unknown;
  try {
    parsed = JSON.parse(data) as unknown;
  } catch {
    throw new MempoolWatchError("Timeout event payload is not valid JSON.");
  }

  if (!isRecord(parsed)) {
    throw new MempoolWatchError("Timeout event payload must be an object.");
  }

  const { address, expiresAt } = parsed;

  if (typeof address !== "string" || !isDogecoinP2pkhAddress(address)) {
    throw new MempoolWatchError("Timeout event is missing a valid address.");
  }

  if (typeof expiresAt !== "string" || expiresAt.length === 0) {
    throw new MempoolWatchError("Timeout event is missing expiresAt.");
  }

  return { address, expiresAt };
};

export const buildMempoolWatchEndpointUrl = (
  endpoint: string,
  address: string,
  minValueBase?: string
): string => {
  const url = new URL(endpoint, "http://localhost");
  const isAbsolute = /^https?:\/\//iu.test(endpoint);
  url.searchParams.set("address", address);
  if (minValueBase !== undefined) {
    url.searchParams.set("minValueBase", minValueBase);
  }

  if (isAbsolute) {
    return url.toString();
  }

  return `${url.pathname}${url.search}`;
};

/**
 * Parse Server-Sent Events frames, honoring named `event:` fields.
 * Comment lines (`:`) and keep-alives are ignored.
 */
export const parseSseChunk = (
  buffer: string,
  chunk: string
): { frames: SseFrame[]; remaining: string } => {
  const combined = `${buffer}${chunk}`;
  const parts = combined.split(/\r?\n\r?\n/u);
  const remaining = parts.pop() ?? "";
  const frames: SseFrame[] = [];

  for (const part of parts) {
    const frame = parseSseFrame(part);
    if (frame) {
      frames.push(frame);
    }
  }

  return { frames, remaining };
};

type WatchOutcome =
  | { type: "appeared"; payload: MempoolWatchAppearedPayload }
  | { type: "timeout"; payload: MempoolWatchTimeoutPayload }
  | { type: "busy" }
  | { type: "error"; error: Error }
  | { type: "closed" };

const dispatchOutcome = (
  options: WatchMempoolOptions,
  outcome: WatchOutcome
): void => {
  switch (outcome.type) {
    case "appeared": {
      options.onAppeared(outcome.payload);
      break;
    }
    case "timeout": {
      options.onTimeout(outcome.payload);
      break;
    }
    case "busy": {
      options.onBusy?.();
      break;
    }
    case "error": {
      options.onError?.(outcome.error);
      break;
    }
    default: {
      break;
    }
  }
};

const readWatchOutcome = async (
  response: Response,
  shouldStop: () => boolean
): Promise<WatchOutcome> => {
  if (response.status === 409) {
    return { type: "busy" };
  }

  if (!response.ok) {
    return {
      error: new MempoolWatchError(
        `Mempool watch failed with status ${response.status}.`
      ),
      type: "error",
    };
  }

  if (!response.body) {
    return {
      error: new MempoolWatchError("Mempool watch response had no body."),
      type: "error",
    };
  }

  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";

  while (!shouldStop()) {
    const { done, value } = await reader.read();
    if (done) {
      break;
    }

    const decoded = decoder.decode(value, { stream: true });
    const parsed = parseSseChunk(buffer, decoded);
    buffer = parsed.remaining;

    for (const frame of parsed.frames) {
      if (frame.event === MEMPOOL_WATCH_APPEARED_EVENT) {
        try {
          return {
            payload: parseMempoolWatchAppearedPayload(frame.data),
            type: "appeared",
          };
        } catch (error) {
          return {
            error:
              error instanceof Error
                ? error
                : new MempoolWatchError("Failed to parse appeared event."),
            type: "error",
          };
        }
      }

      if (frame.event === MEMPOOL_WATCH_TIMEOUT_EVENT) {
        try {
          return {
            payload: parseMempoolWatchTimeoutPayload(frame.data),
            type: "timeout",
          };
        } catch (error) {
          return {
            error:
              error instanceof Error
                ? error
                : new MempoolWatchError("Failed to parse timeout event."),
            type: "error",
          };
        }
      }
    }
  }

  if (shouldStop()) {
    return { type: "closed" };
  }

  return {
    error: new MempoolWatchError(
      "Mempool watch ended before a payment appeared."
    ),
    type: "error",
  };
};

/**
 * Open a one-shot SSE mempool watch session for a receive address.
 * Uses fetch streaming so HTTP statuses like 409 are observable while still
 * dispatching on named `event:` frames.
 */
export const watchMempoolPayment = (
  options: WatchMempoolOptions
): WatchMempoolHandle => {
  const {
    address,
    endpoint,
    fetchImpl = fetch,
    minValueBase,
    signal,
  } = options;

  if (!isDogecoinP2pkhAddress(address)) {
    throw new MempoolWatchError("Cannot watch an invalid Dogecoin address.");
  }

  if (minValueBase !== undefined && !isNonNegativeBaseUnits(minValueBase)) {
    throw new MempoolWatchError(
      "minValueBase must be a non-negative integer string."
    );
  }

  const controller = new AbortController();
  let settled = false;

  const close = () => {
    if (settled) {
      return;
    }
    settled = true;
    controller.abort();
  };

  if (signal) {
    if (signal.aborted) {
      close();
      return { close };
    }
    signal.addEventListener("abort", close, { once: true });
  }

  const url = buildMempoolWatchEndpointUrl(endpoint, address, minValueBase);

  void (async () => {
    try {
      const response = await fetchImpl(url, {
        headers: {
          Accept: "text/event-stream",
          "Cache-Control": "no-store",
        },
        method: "GET",
        signal: controller.signal,
      });

      if (settled) {
        return;
      }

      const outcome = await readWatchOutcome(response, () => settled);
      if (settled || outcome.type === "closed") {
        return;
      }

      settled = true;
      controller.abort();
      dispatchOutcome(options, outcome);
    } catch (error: unknown) {
      if (
        settled ||
        controller.signal.aborted ||
        (error instanceof DOMException && error.name === "AbortError")
      ) {
        return;
      }

      settled = true;
      dispatchOutcome(options, {
        error:
          error instanceof Error
            ? error
            : new MempoolWatchError("Mempool watch connection failed."),
        type: "error",
      });
    }
  })();

  return { close };
};

const AMOUNT_PATTERN = /^(?:0|[1-9]\d*)(?:\.\d{1,8})?$/u;

export class PaymentUriError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "PaymentUriError";
  }
}

/**
 * Validate a suggested DOGE amount as a positive decimal string with at most
 * 8 fractional digits.
 */
export const normalizeDogecoinAmount = (amount: string): string => {
  const trimmed = amount.trim();

  if (!AMOUNT_PATTERN.test(trimmed)) {
    throw new PaymentUriError(
      "Amount must be a positive decimal string with up to 8 decimal places."
    );
  }

  const value = Number(trimmed);
  if (!Number.isFinite(value) || value <= 0) {
    throw new PaymentUriError("Amount must be greater than zero.");
  }

  const [whole, fractional] = trimmed.split(".");
  if (!fractional) {
    return whole;
  }

  const normalizedFractional = fractional.replace(/0+$/u, "");
  return normalizedFractional ? `${whole}.${normalizedFractional}` : whole;
};

export const buildDogecoinPaymentUri = (
  address: string,
  amount?: string
): string => {
  if (!amount) {
    return `dogecoin:${address}`;
  }

  const normalized = normalizeDogecoinAmount(amount);
  return `dogecoin:${address}?amount=${normalized}`;
};

